import * as React from 'react'
import { graphql } from 'gatsby'
import { IGatsbyImageData, GatsbyImage, getImage } from 'gatsby-plugin-image'
import Lightbox from 'yet-another-react-lightbox'
import Zoom from 'yet-another-react-lightbox/plugins/zoom'
import Fullscreen from 'yet-another-react-lightbox/plugins/fullscreen'
import 'yet-another-react-lightbox/styles.css'

import "../scss/main.scss"

import Header from "../components/Header"
import Footer from "../components/Footer"

const MAX_GRID_IMAGES = 72

interface PhotoGridNode {
  name: string
  relativeDirectory: string
  sourceInstanceName: string
  publicURL: string
  childImageSharp: {
    thumb: IGatsbyImageData
    full: IGatsbyImageData
  }
}

interface PageProps {
  data: {
    photography: { nodes: PhotoGridNode[] }
    photoJourneys: { nodes: PhotoGridNode[] }
  }
}

const PhotoGridPage: React.FC<PageProps> = ({ data }) => {
  const [lightboxIndex, setLightboxIndex] = React.useState(-1)

  const gridImages = React.useMemo(() => {
    const combined = [
      ...data.photography.nodes,
      ...data.photoJourneys.nodes,
    ]

    // Fisher-Yates shuffle
    for (let i = combined.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1))
      ;[combined[i], combined[j]] = [combined[j], combined[i]]
    }

    return combined.slice(0, MAX_GRID_IMAGES)
  }, [data.photography.nodes, data.photoJourneys.nodes])

  const lightboxSlides = gridImages.map((node) => ({
    src: node.publicURL,
  }))

  const getGridItemClass = (node: PhotoGridNode, index: number): string => {
    const thumbData = node.childImageSharp.thumb
    const width = thumbData.width || 1
    const height = thumbData.height || 1
    const ratio = width / height

    // Every 7th image gets featured (2x2) regardless
    if (index % 7 === 0) return 'photo-grid__item photo-grid__item--featured'

    // Portrait images (taller than wide) get tall cells
    if (ratio < 0.75) return 'photo-grid__item photo-grid__item--tall'

    // Wide landscape images get wide cells
    if (ratio > 1.4) return 'photo-grid__item photo-grid__item--wide'

    return 'photo-grid__item'
  }

  const formatLabel = (dir: string): string => {
    return dir.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ')
  }

  return (
    <div className="container">
      <Header />

      <svg className="photo-grid__svg-filters" aria-hidden="true">
        <defs>
          <filter id="duotone-ocean">
            <feColorMatrix
              type="matrix"
              values="0.2 0.5 0.3 0 0
                      0.1 0.4 0.5 0 0
                      0.0 0.2 0.8 0 0
                      0   0   0   1 0"
            />
          </filter>
        </defs>
      </svg>

      <div className="photo-grid__hero">
        <h1>Photo Grid</h1>
        <p>A curated mosaic blending birds, journeys, and landscapes into one creative showcase.</p>
        <div className="accent-line"></div>
      </div>

      <div className="photo-grid">
        {gridImages.map((node, index) => {
          const image = getImage(node.childImageSharp.thumb)
          if (!image) return null

          return (
            <div
              key={`${node.name}-${index}`}
              className={getGridItemClass(node, index)}
              onClick={() => setLightboxIndex(index)}
            >
              <GatsbyImage
                image={image}
                alt={`${formatLabel(node.relativeDirectory)} - ${node.name}`}
                className="photo-grid__image"
                objectFit="cover"
              />
              <div className="photo-grid__overlay">
                <span className="photo-grid__label">
                  {formatLabel(node.relativeDirectory)}
                </span>
              </div>
            </div>
          )
        })}
      </div>

      <div className="back-to-top-container">
        <button
          className="back-to-top"
          onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
        >
          ↑ Back to Top
        </button>
      </div>

      <Lightbox
        open={lightboxIndex >= 0}
        close={() => setLightboxIndex(-1)}
        index={lightboxIndex}
        slides={lightboxSlides}
        plugins={[Zoom, Fullscreen]}
        zoom={{
          maxZoomPixelRatio: 3,
          scrollToZoom: true,
        }}
        controller={{
          closeOnPullDown: true,
          closeOnPullUp: true,
          closeOnBackdropClick: true,
        }}
        carousel={{
          finite: false,
          spacing: 0,
          padding: 0,
        }}
        animation={{
          fade: 250,
          swipe: 500,
          navigation: 500,
          easing: {
            fade: "ease-out",
            swipe: "ease-in-out",
            navigation: "ease-in-out",
          },
        }}
      />

      <Footer />
    </div>
  )
}

export const pageQuery = graphql`
  query PhotoGridPageQuery {
    photography: allFile(
      filter: {
        sourceInstanceName: { eq: "photography" }
        relativeDirectory: { ne: "", nin: ["new-year-26"] }
      }
      sort: { name: ASC }
    ) {
      nodes {
        name
        relativeDirectory
        sourceInstanceName
        publicURL
        childImageSharp {
          thumb: gatsbyImageData(
            width: 600
            placeholder: BLURRED
          )
          full: gatsbyImageData(layout: FULL_WIDTH)
        }
      }
    }
    photoJourneys: allFile(
      filter: {
        sourceInstanceName: { eq: "photo-journeys" }
        relativeDirectory: { ne: "" }
      }
      sort: { name: ASC }
    ) {
      nodes {
        name
        relativeDirectory
        sourceInstanceName
        publicURL
        childImageSharp {
          thumb: gatsbyImageData(
            width: 600
            placeholder: BLURRED
          )
          full: gatsbyImageData(layout: FULL_WIDTH)
        }
      }
    }
  }
`

export default PhotoGridPage
